function(container, apiUrl, tables) {
  // エラー情報の初期化
  const errorInfo = {
    title: "システムエラーが発生しました",
    message: "予期しないエラーが発生しました。しばらく時間をおいてから再度お試しください。",
    code: "ERR_500_INTERNAL",
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit', 
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    solution: "• ページを再読み込みして再度お試しください<br>• 問題が解決しない場合は管理者にお問い合わせください<br>• 緊急の場合は直接管理者までご連絡ください",
    details: "TypeError: Cannot read property 'id' of undefined\n  at WorkRecordService.save (work-record.service.js:45:12)\n  at async saveWorkRecord (work-record.component.js:128:18)"
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      Object.assign(errorInfo, errorData);
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  container.querySelector('#error-title').textContent = errorInfo.title;
  container.querySelector('#error-message').textContent = errorInfo.message;
  container.querySelector('#error-code').textContent = errorInfo.code;
  container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;
  container.querySelector('#error-solution').innerHTML = errorInfo.solution;
  container.querySelector('#error-details pre').textContent = errorInfo.details;

  // エラー詳細の表示/非表示切り替え
  container.querySelector('#btn-toggle-details').addEventListener('click', () => {
    const detailsDiv = container.querySelector('#error-details');
    const toggleBtn = container.querySelector('#btn-toggle-details');

    if (detailsDiv.classList.contains('hidden')) {
      detailsDiv.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsDiv.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  });

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    // 前のページに戻って再実行
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（メイン画面）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', () => {
    // 緊急報告画面に遷移してエラー情報を引き継ぐ
    const errorReport = {
      type: 'システムエラー',
      title: errorInfo.title,
      description: `${errorInfo.message}\n\nエラーコード: ${errorInfo.code}\n発生時刻: ${errorInfo.timestamp}\n\n詳細:\n${errorInfo.details}`,
      priority: '高',
      reportedAt: new Date().toISOString()
    };

    // 緊急報告画面にエラー情報を渡して遷移
    window.showScreen('scr-1778907330826', { errorReport });
  });

  // エラーログの記録
  if (window.aivicApi) {
    const logData = {
      検出対象テーブル: 'システム',
      検出対象レコードID: 'system-error',
      ユーザーID: window.currentUser?.id || 'unknown',
      異常値種別: 'システムエラー',
      検出項目: 'アプリケーション実行',
      検出値: errorInfo.code,
      閾値: '正常動作',
      重要度: '高',
      確認状況: '未確認',
      通知送信フラグ: false,
      検出日時: new Date().toISOString(),
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    // 異常値検出ログテーブルに記録（テーブルインデックス4）
    window.aivicApi.save(4, logData).catch(err => {
      console.warn('エラーログの記録に失敗しました:', err);
    });
  }
}
